questions.solution:
function newest(versions) {
  const parse = (v) => v.split(".").map(Number);
  let best = versions[0];
  for (const version of versions.slice(1)) {
    const a = parse(version);
    const b = parse(best);
    const diff = a[0] - b[0] || a[1] - b[1] || a[2] - b[2];
    if (diff > 0) best = version;
  }
  return best;
}

console.log(newest(["2.9.0", "2.10.0", "2.1.3"]));
console.log(newest(["1.0.0", "0.12.4", "1.0.11", "1.0.2"]));

