questions.solution:
function listDeps(pkg) {
  const lines = [];
  for (const section of ["dependencies", "devDependencies"]) {
    for (const [name, range] of Object.entries(pkg[section] ?? {})) {
      lines.push(`${section}: ${name} ${range}`);
    }
  }
  return lines;
}

const app = { dependencies: { ms: "^2.1.3" }, devDependencies: { prettier: "^3.9.9" } };
console.log(listDeps(app).join("\n"));
console.log(listDeps({ name: "empty" }).length);

