function filesToPublish(folderFiles, allow) {
  const always = ["package.json", "README.md"];
  return folderFiles.filter((file) => allow.includes(file) || always.includes(file));
}

const folder = [".env", "README.md", "index.js", "index.test.js", "notes.txt", "package.json"];
console.log(filesToPublish(folder, ["index.js"]).join(" "));

